BEGIN TRANSACTION READ ONLY; SET LOCAL statement_timeout = '10s'; SET LOCAL lock_timeout = '2s'; SELECT id, name, public, file_size_limit, allowed_mime_types, type::text, versioning_status, lifecycle_configuration IS NOT NULL AS lifecycle_configured, CASE WHEN jsonb_typeof(lifecycle_configuration->'rules') = 'array' THEN jsonb_array_length(lifecycle_configuration->'rules') END AS lifecycle_rule_count FROM storage.buckets WHERE id IN ('saga', 'audio-recordings') ORDER BY id; ROLLBACK;
